question.solution:
def is_balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        else:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

print(is_balanced('{[()]}'))
print(is_balanced('([)]'))
print(is_balanced(''))
print(is_balanced('((('))
